mapper.select:
select `e`.*,u.real_name,u.image_url, ud.real_name as doctor_real_name from `evaluate` e   left join `user` u on e.user_id = u.id
   left join `user` ud on e.doctor_user_id = ud.id
   where 1=1

       and `e`.id = #{id}


        and e.user_id = #{userId}


        and e.doctor_user_id = #{doctorUserId}


        and u.real_name like concat('%',#{realName},'%')


        and ud.real_name like concat('%',#{doctorRealName},'%')

    order by `e`.create_time desc
